import { ScreenLayout, FocalElement } from '../types/designer';

export function exportScreenToC(screen: ScreenLayout): string {
  const sanitizeIdentifier = (str: string) => str.toLowerCase().replace(/[^a-z0-9_]/g, '_');
  const screenId = sanitizeIdentifier(screen.id);

  let cCode = `/**
 * @file focal_ui_${screenId}.c
 * @brief Auto-generated by Focal Studio Designer for ESP32 TFT 3.5" (480x320)
 * Screen: ${screen.name}
 * Elements count: ${screen.elements.length}
 */

#include "lvgl.h"
#include "focal_theme.h"
#include "focal_icons.h"

// Element Layout Table (480x320 Viewport)
typedef struct {
    const char *id;
    int16_t x;
    int16_t y;
    int16_t w;
    int16_t h;
    uint16_t radius;
    uint32_t accent_hex;
    const char *text;
    const char *icon_id;
} focal_elem_desc_t;

static const focal_elem_desc_t ${screenId}_elements[] = {
`;

  screen.elements.forEach((el) => {
    // 1. Properly escape backslashes first, then quotes, newlines, carriage returns
    const cleanText = (el.text || '')
      .replace(/\\/g, '\\\\')
      .replace(/"/g, '\\"')
      .replace(/\r/g, '')
      .replace(/\n/g, '\\n');
    const cleanIcon = el.icon ? `"${el.icon.replace(/[^a-zA-Z0-9_]/g, '')}"` : 'NULL';
    // 2. Validate hex color
    const hexMatch = (el.accentColor || '').match(/^#?([0-9A-Fa-f]{6})$/);
    const accentHex = hexMatch ? `0x${hexMatch[1].toUpperCase()}` : '0x60A5FA';
    // 3. Clamp dimensions and coordinates within 480x320 bounds
    const safeW = Math.max(16, Math.min(480, Math.round(el.w || 16)));
    const safeH = Math.max(16, Math.min(320, Math.round(el.h || 16)));
    const safeX = Math.max(0, Math.min(480 - safeW, Math.round(el.x || 0)));
    const safeY = Math.max(0, Math.min(320 - safeH, Math.round(el.y || 0)));
    const safeRadius = Math.max(0, Math.round(el.radius || 0));
    const safeId = (el.id || 'elem').replace(/[^a-zA-Z0-9_]/g, '_');
    cCode += `    { "${safeId}", ${safeX}, ${safeY}, ${safeW}, ${safeH}, ${safeRadius}, ${accentHex}, "${cleanText}", ${cleanIcon} },\n`;
  });

  cCode += `};

#define ${screenId.toUpperCase()}_ELEMENT_COUNT ${screen.elements.length}

/**
 * @brief Builds the ${screen.name} in LVGL v8
 */
lv_obj_t* focal_ui_create_${screenId}(lv_obj_t *parent) {
    lv_obj_t *screen = lv_obj_create(parent);
    lv_obj_set_size(screen, 480, 320);
    lv_obj_add_style(screen, &focal_style_screen, 0);
    lv_obj_clear_flag(screen, LV_OBJ_FLAG_SCROLLABLE);

    for (int i = 0; i < ${screenId.toUpperCase()}_ELEMENT_COUNT; i++) {
        const focal_elem_desc_t *desc = &${screenId}_elements[i];
        lv_obj_t *obj = NULL;

        if (desc->radius >= 999) {
            // Pill element
            obj = lv_btn_create(screen);
            lv_obj_set_style_radius(obj, LV_RADIUS_CIRCLE, 0);
        } else if (desc->radius > 0) {
            // Squircle Card or Rounded Button
            obj = lv_btn_create(screen);
            lv_obj_set_style_radius(obj, desc->radius, 0);
        } else {
            // Plain container / Label
            obj = lv_label_create(screen);
        }

        lv_obj_set_pos(obj, desc->x, desc->y);
        lv_obj_set_size(obj, desc->w, desc->h);
        lv_obj_set_style_bg_color(obj, lv_color_hex(desc->accent_hex), 0);
        lv_obj_set_style_border_color(obj, FOCAL_COLOR_BORDER_SUBTLE, 0);
        lv_obj_set_style_border_width(obj, 1, 0);

        if (lv_obj_check_type(obj, &lv_label_class)) {
            lv_label_set_text(obj, desc->text);
            lv_obj_set_style_text_color(obj, FOCAL_COLOR_TEXT_PRIMARY, 0);
        } else {
            lv_obj_t *lbl = lv_label_create(obj);
            lv_label_set_text(lbl, desc->text);
            lv_obj_center(lbl);
            lv_obj_set_style_text_color(lbl, FOCAL_COLOR_TEXT_PRIMARY, 0);
        }
    }

    return screen;
}
`;

  return cCode;
}
